    private static final long REFRESH_TOKEN_EXPIRE_SECONDS = 86400; // 24 hours
    private static final long ONE_TIME_TOKEN_EXPIRE_SECONDS = 300; // 5 minutes

    // Token storage in database
    private static final Map<String, TokenEntity> TOKENS_DB = new ConcurrentHashMap<>();
    private static final Map<String, User> USERS_DB = new ConcurrentHashMap<>();

    // Track token rotation state
    private static final AtomicBoolean rotationEnabled = new AtomicBoolean(true);

    // One-time token tracking
    private static final Map<String, TokenEntity> ONE_TIME_TOKENS = new ConcurrentHashMap<>();

    // Track concurrent requests for token renewal
    private static final AtomicInteger concurrentRenewAttempts = new AtomicInteger(0);

    public static void main(String[] args) {
        SpringApplication.run(AuthService.class, args);
    }

    // ============ Authentication Endpoints ============

    /**
     * Login endpoint - POST /api/auth/login
     * Accepts username and password, returns tokens and sets refresh token cookie
     */
    public Map<String, String> login(HttpServletRequest request) throws IOException {
        // Read request body using Jackson or custom parser
