    /**
     * Logout endpoint - POST /api/auth/logout
     * Accepts Access Token in Authorization header
     * Invalidates all tokens for the user
     */
    public Map<String, Object> logout(HttpServletRequest request) {
        String authorizationHeader = request.getHeader("Authorization");

        // Extract access token from Bearer token
        if (authorizationHeader != null && authorizationHeader.startsWith("Bearer ")) {
            String accessToken = authorizationHeader.substring(7);

            // Find and invalidate user's tokens
            invalidateUserTokens(request);

            return Map.of("message", "Logged out successfully");
        } else {
            return Map.of("message", "Unauthorized - Invalid token");
        }
    }

    /**
     * Validate token endpoint - POST /api/auth/validate-token
     * Accepts token as JSON parameter
     * Validates and consumes one-time token
     */
    public Map<String, Object> validateToken(HttpServletRequest request, String token) {
        // Find the token entity from database
        TokenEntity tokenEntity = TOKENS_DB.get(token);

        if (tokenEntity == null) {
            return Map.of("valid", false, "message", "Token not found");
        }

        // Check if token is revoked
        if (tokenEntity.isRevoked()) {
            return Map.of("valid", false, "message", "Token has been revoked");
        }

        // Check if token is consumed (one-time token)
        if (tokenEntity.isConsumed()) {
            return Map.of("valid", false, "message", "Token has already been consumed");
        }

        // Check expiration
        if (tokenEntity.getExpiresAt().isBefore(Instant.now())) {
            return Map.of("valid", false, "message", "Token has expired");
        }

        // Token is valid - consume it atomically
        tokenEntity.markAsConsumed();

        return Map.of("valid", true, "message", "Token validated successfully");
    }

    /**
     * Renew endpoint - POST /api/auth/renew
     * Accepts Refresh Token from Cookie (name: refreshToken) OR Header (key: refreshToken)
     * If both present, Cookie takes precedence
     * Rotates tokens atomically
     */
    public Map<String, Object> renew(HttpServletRequest request) throws IOException {
        // Get Refresh Token from Cookie or Header
        String refreshToken = null;

        // Check Cookie first (takes precedence)
        Cookie[] cookies = request.getCookies();
        if (cookies != null) {
            for (Cookie cookie : cookies) {
                if (cookie.getName().equals("refreshToken") && !cookie.isExpired() && !cookie.isInvalid()) {
                    refreshToken = cookie.getValue();
                    break;
                }
            }
        }

        // If no cookie, check Header
        if (refreshToken == null) {
            HttpServletRequest headerRequest = (HttpServletRequest) request;
            String headerValue = headerRequest.getHeader("refreshToken");
            if (headerValue != null && !headerValue.isEmpty()) {
                refreshToken = headerValue;
            }
        }

        // If no valid refresh token, return 401
        if (refreshToken == null || refreshToken.isEmpty()) {
            return Map.of("accessToken", "", "message", "Refresh token missing or invalid");
        }

        // Find current token entity
        TokenEntity currentToken = null;
        for (Map.Entry<String, TokenEntity> entry : TOKENS_DB.entrySet()) {
            String tokenValue = entry.getKey();
            // Token value should match the refresh token (or be associated with user)
            // Actually, refresh token is stored separately, we need to find by user_id or token
            // According to requirements: "Atomically revoke current Refresh Token"
            // So we need to find token by its value or user association
            // Let's assume token value matches refresh token for simplicity
            if (tokenValue.equals(refreshToken)) {
                currentToken = entry.getValue();
                break;
            }
        }

        if (currentToken == null) {
            return Map.of("accessToken", "", "message", "Invalid refresh token");
        }

        // Check if token is revoked
        if (currentToken.isRevoked()) {
            return Map.of("accessToken", "", "message", "Refresh token has been revoked");
        }

        // Check if token is expired
        if (currentToken.getExpiresAt().isBefore(Instant.now())) {
            return Map.of("accessToken", "", "message", "Refresh token has expired");
        }

        // Rotate tokens atomically:
        // 1. Revoke current Refresh Token
        // 2. Issue new Refresh Token
        // 3. Issue new Access Token
        // 4. Issue new One-Time Token

        // Revoke current token
        currentToken.markAsRevoked();

        // Create new tokens
        String newAccessToken = generateNewAccessToken();
        String newRefreshToken = generateNewRefreshToken();
        String newOneTimeToken = generateNewOneTimeToken();

        // Update database with new tokens
        TokenEntity newAccessTokenEntity = new TokenEntity(
            newAccessToken,
            request.getUserPrincipal().toString(), // user_id
            "ACCESS",
            Instant.now(),
            Instant.now().plus(ACCESS_TOKEN_EXPIRE_MINS, java.time.temporal.ChronoUnit.MINUTES),
            false,
            false
        );
        TOKENS_DB.put(newAccessTokenEntity.getKey(), newAccessTokenEntity);

        TokenEntity newRefreshTokenEntity = new TokenEntity(
            newRefreshToken,
            request.getUserPrincipal().toString(),
            "REFRESH",
            Instant.now(),
            Instant.now().plus(REFRESH_TOKEN_EXPIRE_SECONDS, java.time.temporal.ChronoUnit.SECONDS),
            false,
            false
        );
        TOKENS_DB.put(newRefreshTokenEntity.getKey(), newRefreshTokenEntity);

        TokenEntity newOneTimeTokenEntity = new TokenEntity(
            newOneTimeToken,
            request.getUserPrincipal().toString(),
            "ONE_TIME",
            Instant.now(),
            Instant.now().plus(ONE_TIME_TOKEN_EXPIRE_SECONDS, java.time.temporal.ChronoUnit.SECONDS),
            false,
            false
        );
        TOKENS_DB.put(newOneTimeTokenEntity.getKey(), newOneTimeTokenEntity);

        // Set new tokens in response
        return Map.of(
            "accessToken" -> newAccessToken,
            "message" -> "Token renewal successful"
        );

        // Also set new refresh token as cookie
        returnResponseCookie("refreshToken", newRefreshToken);
    }

    /**
     * Generate unique token identifiers
     */
    private String generateNewAccessToken() {
        // Use UUID or timestamp based on user_id to ensure uniqueness
        return "access_token_" + System.currentTimeMillis() + "_" + 
               new Random().nextInt(10000);
    }

    private String generateNewRefreshToken() {
        return "refresh_token_" + System.currentTimeMillis() + "_" + 
               new Random().nextInt(10000);
    }

    private String generateNewOneTimeToken() {
        return "one_time_token_" + System.currentTimeMillis() + "_" + 
               new Random().nextInt(10000);
    }

    /**
     * Invalidate all tokens for authenticated user
     */
    private void invalidateUserTokens(HttpServletRequest request) {
        // Find user by authentication mechanism (e.g., from Authorization header)
        // Extract user_id from token or request context
        // For simplicity, assume we have user info in request

        // Get user principal from auth header
        String userPrincipal = request.getHeader("X-User-Principal");
        if (userPrincipal == null) {
            userPrincipal = request.getAttribute("userPrincipal");
        }

        if (userPrincipal == null) {
            return;
        }

        // Get user_id from user principal or token metadata
        String userId = userPrincipal; // Simplified assumption

        // Invalidate all tokens for this user
        // Clear database entries for this user's tokens
        // Note: In production, use proper query with user_id filter
        TOKENS_DB.values().stream()
            .filter(token -> token.getUser_id().equals(userId))
            .forEach(token -> {
                // Revoke the token
                token.markAsRevoked();
                // Delete from database
                TOKENS_DB.remove(token.getKey());
            });

        // Also clear ONE_TIME_TOKENS for this user
        ONE_TIME_TOKENS.values().stream()
            .filter(token -> token.getUser_id().equals(userId))
            .forEach(token -> {
                token.markAsConsumed(); // Already marked as consumed
                ONE_TIME_TOKENS.remove(token.getKey());
            });
    }

    /**
     * Background cleanup task - scheduled every 10 seconds
     */
    @Scheduled(cron = "0/* * * * *")
    public void cleanupExpiredTokens() {
        long startTime = Instant.now();
        int deletedCount = 0;

        // Iterate through all tokens in database
        for (TokenEntity token : TOKENS_DB.values()) {
            // Check if token needs cleanup
            boolean shouldDelete = false;

            // Check if expired
            if (token.getExpiresAt().isBefore(Instant.now())) {
                shouldDelete = true;
            }

            // Check if revoked
            if (token.isRevoked()) {
                shouldDelete = true;
            }

            // Check if consumed (one-time tokens)
            if (token.isConsumed()) {
                shouldDelete = true;
            }

            // Clean up if needed
            if (shouldDelete) {
                // Delete from database
                TOKENS_DB.remove(token.getKey());
                ONE_TIME_TOKENS.remove(token.getKey());

                // Log cleanup action
                System.out.println("[CLEANUP] Deleted " + (deletedCount + 1) + " tokens");
                deletedCount++;
            }
        }

        // Also cleanup one-time tokens
        for (TokenEntity token : ONE_TIME_TOKENS.values()) {
            if (token.isConsumed() || token.isRevoked() || token.getExpiresAt().isBefore(Instant.now())) {
                TOKENS_DB.remove(token.getKey());
                ONE_TIME_TOKENS.remove(token.getKey());
                System.out.println("[CLEANUP] Deleted " + (deletedCount + 1) + " tokens");
                deletedCount++;
            }
        }

        // Log total cleanup
        System.out.println("[CLEANUP] Total tokens cleaned: " + deletedCount);
    }

    // ============ Token Entity Class ============

    private static class TokenEntity {
        private String tokenValue;
        private String userId;
        private String tokenType;
        private Instant issuedAt;
        private Instant expiresAt;
        private boolean isRevoked;
