        public void markAsRevoked() {
            isRevoked = true;
        }
    }

    // ============ User Entity Class ============

    private static class User {
        private String username;
        private String userId;

        User(String username, String userId) {
            this.username = username;
            this.userId = userId;
        }

        public String getUsername() {
            return username;
        }

        public String getUserId() {
            return userId;
        }
    }
}
