package com.example.authentication;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.config.annotation.CorsRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

import javax.servlet.http.Cookie;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

@SpringBootApplication
public class AuthService {

    private static final String ACCESS_TOKEN_LIFETIME = "10 minutes";
    private static final String REFRESH_TOKEN_LIFETIME = "1 day";
    private static final String ONE_TIME_TOKEN_LIFETIME = "5 minutes";

    private static final long ACCESS_TOKEN_EXPIRE_MINS = 600; // 10 minutes
    private static final long REFRESH_TOKEN_EXPIRE_SECONDS = 86400; // 24 hours
    private static final long ONE_TIME_TOKEN_EXPIRE_SECONDS = 300; // 5 minutes

    // Token storage - Map from tokenValue (unique identifier) to TokenEntity
    private static final Map<String, TokenEntity> TOKENS_DB = new ConcurrentHashMap<>();

    // User storage - Map from userId to UserEntity
    private static final Map<String, UserEntity> USERS_DB = new ConcurrentHashMap<>();

    // One-time token tracking - Map from tokenValue to TokenEntity
    private static final Map<String, TokenEntity> ONE_TIME_TOKENS = new ConcurrentHashMap<>();

    // Track concurrent renewal attempts using AtomicInteger for thread safety
    private static final AtomicInteger concurrentRenewAttempts = new AtomicInteger(0);

    // Scheduled cleanup task
    private static final java.util.concurrent.ExecutorscheduledTaskUtils.ScheduledExecutorService cleanupExecutor = 
            Executors.newScheduledThreadPool(1, new java.util.concurrent.ThreadFactory() {
                @Override
                public Thread newThread(Runnable r) {
                    Thread t = new Thread(r, "TokenCleanup");
                    t.setDaemon(true);
                    return t;
                }
            });

    public static void main(String[] args) {
        SpringApplication.run(AuthService.class, args);

        // Start cleanup scheduler
        cleanupExecutor.scheduleAtFixedRate(AuthService::cleanupExpiredTokens, 10, 10, TimeUnit.SECONDS);
    }

    // ============ API Endpoints ============

    /**
     * POST /api/auth/login
     * Accepts username and password, returns tokens and sets refresh token cookie
     */
    @PostMapping("/api/auth/login")
    public ResponseEntity<Map<String, String>> login(@RequestBody(required = false) LoginRequest loginRequest) 
            throws IOException {

        // Validate input
        if (loginRequest == null || loginRequest.getUsername() == null || 
            loginRequest.getUsername().isEmpty() || 
            loginRequest.getPassword() == null || loginRequest.getPassword().isEmpty()) {
            return ResponseEntity.badRequest().build();
        }

        // Find user by username
        UserEntity user = USERS_DB.getIfPresent(loginRequest.getUsername());
        if (user == null) {
            // User not found - return error
            return ResponseEntity.status(404).body(null);
        }

        // Validate credentials (in real system, compare with hash)
        // For this task, assume any non-empty username/password is valid
        // Issue three tokens atomically:
        // 1. Access Token (10 min)
        // 2. Refresh Token (24 hours)
        // 3. One-Time Token (5 min)

        String accessToken = generateNewAccessToken(user.getUserId());
        String refreshToken = generateNewRefreshToken(user.getUserId());
        String oneTimeToken = generateNewOneTimeToken();

        // Create TokenEntities
        TokenEntity accessTokenEntity = new TokenEntity(
            accessToken,
            user.getUserId(),
            "ACCESS",
            Instant.now(),
            Instant.now().plus(ACCESS_TOKEN_EXPIRE_MINS, ChronoUnit.MINUTES),
            false,
            false
        );

        TokenEntity refreshTokenEntity = new TokenEntity(
            refreshToken,
            user.getUserId(),
            "REFRESH",
            Instant.now(),
            Instant.now().plus(REFRESH_TOKEN_EXPIRE_SECONDS, ChronoUnit.SECONDS),
            false,
            false
        );

        TokenEntity oneTimeTokenEntity = new TokenEntity(
            oneTimeToken,
            user.getUserId(),
            "ONE_TIME",
            Instant.now(),
            Instant.now().plus(ONE_TIME_TOKEN_EXPIRE_SECONDS, ChronoUnit.SECONDS),
            false,
            false
        );

        // Store in database
        TOKENS_DB.put(accessToken, accessTokenEntity);
        TOKENS_DB.put(refreshToken, refreshTokenEntity);
        ONE_TIME_TOKENS.put(oneTimeToken, oneTimeTokenEntity);

        // Create response with tokens
        Map<String, String> response = new HashMap<>();
        response.put("accessToken", accessToken);
        response.put("oneTimeToken", oneTimeToken);

        // Set Refresh Token as HTTP-only cookie
        HttpServletResponse response = (HttpServletResponse) getResponse();
        Cookie refreshTokenCookie = new Cookie("refreshToken", refreshToken);
        refreshTokenCookie.setHttpOnly(true);
        refreshTokenCookie.setMaxAge(86400); // 24 hours
        response.addCookie(refreshTokenCookie);

        // Return JSON response
        return ResponseEntity.ok(Map.of("accessToken" -> accessToken, "oneTimeToken" -> oneTimeToken));
    }

    /**
     * POST /api/auth/renew
     * Accepts Refresh Token from Cookie (name: refreshToken) OR Header (key: refreshToken)
     * If both present, Cookie takes precedence
     * Rotates tokens atomically
     */
    @PostMapping("/api/auth/renew")
    public ResponseEntity<Map<String, Object>> renew(
            @RequestParam(name = "refreshToken", required = false) String refreshTokenFromHeader,
            @CookieValue(value = "refreshToken", required = false, name = "refreshToken") String refreshTokenFromCookie) 
            throws IOException {

        // Determine which source has the token
        // Cookie takes precedence over Header
        String effectiveRefreshToken = refreshTokenFromCookie != null && !refreshTokenFromCookie.isEmpty() 
                ? refreshTokenFromCookie 
                : (refreshTokenFromHeader != null && !refreshTokenFromHeader.isEmpty() ? refreshTokenFromHeader : "");

        // If no valid refresh token, return 401
        if (effectiveRefreshToken == null || effectiveRefreshToken.isEmpty()) {
            return ResponseEntity.status(401).body(Map.of("accessToken", "", "message", "Refresh token missing or invalid"));
        }

        // Check if refresh token is expired
        TokenEntity currentToken = TOKENS_DB.get(effectiveRefreshToken);
        if (currentToken == null) {
            return ResponseEntity.status(401).body(Map.of("accessToken", "", "message", "Refresh token not found"));
        }

        // Check if token is revoked
        if (currentToken.isRevoked()) {
            return ResponseEntity.status(401).body(Map.of("accessToken", "", "message", "Refresh token has been revoked"));
        }

        // Check if token is expired
        if (currentToken.getExpiresAt().isBefore(Instant.now())) {
            return ResponseEntity.status(401).body(Map.of("accessToken", "", "message", "Refresh token has expired"));
        }

        // Handle concurrent renewal attempts - use atomic counter
        // Only allow one renewal to succeed for the same refresh token
        // Increment counter, if > 1, reject (409 Conflict)
        int currentAttempt = concurrentRenewAttempts.getAndIncrement();
        if (currentAttempt > 1) {
            // Concurrent access detected - reject
            return ResponseEntity.status(409).body(Map.of("accessToken", "", "message", "Concurrent renewal attempt detected"));
