            newRefreshToken,
            currentToken.getUserId(),
            "REFRESH",
            Instant.now(),
            Instant.now().plus(REFRESH_TOKEN_EXPIRE_SECONDS, ChronoUnit.SECONDS),
            false,
            false
        );
        TOKENS_DB.put(newRefreshTokenEntity.getKey(), newRefreshTokenEntity);

        TokenEntity newAccessTokenEntity = new TokenEntity(
            newAccessToken,
            currentToken.getUserId(),
            "ACCESS",
            Instant.now(),
            Instant.now().plus(ACCESS_TOKEN_EXPIRE_MINS, ChronoUnit.MINUTES),
            false,
            false
        );
        TOKENS_DB.put(newAccessTokenEntity.getKey(), newAccessTokenEntity);

        TokenEntity newOneTimeTokenEntity = new TokenEntity(
            newOneTimeToken,
            currentToken.getUserId(),
            "ONE_TIME",
            Instant.now(),
            Instant.now().plus(ONE_TIME_TOKEN_EXPIRE_SECONDS, ChronoUnit.SECONDS),
            false,
            false
        );
        TOKENS_DB.put(newOneTimeTokenEntity.getKey(), newOneTimeTokenEntity);

        // Set new tokens in response
        Map<String, Object> response = new HashMap<>();
        response.put("accessToken", newAccessToken);

        // Return new refresh token as cookie
        HttpServletResponse response = (HttpServletResponse) getResponse();
        Cookie refreshTokenCookie = new Cookie("refreshToken", newRefreshToken);
        refreshTokenCookie.setHttpOnly(true);
        refreshTokenCookie.setMaxAge(86400);
        response.addCookie(refreshTokenCookie);

        return ResponseEntity.ok(Map.of("accessToken" -> newAccessToken));
    }

    /**
     * POST /api/auth/logout
     * Accepts Access Token in Authorization header
     * Returns 401 if Access Token is missing or invalid
     */
    @PostMapping("/api/auth/logout")
    public ResponseEntity<Map<String, Object>> logout(
