        }

        // Find user entity by user_id
        UserEntity user = USERS_DB.getIfPresent(accessTokenEntity.getUserId());
        if (user == null) {
            return ResponseEntity.status(404).body(Map.of("message", "User not found"));
        }

        // Invalidate all tokens for this user:
        // 1. Revoke Access Token
        accessTokenEntity.markAsRevoked();
        TOKENS_DB.remove(accessTokenEntity.getKey());

        // 2. Revoke Refresh Token (if exists for this user)
