                .stream()
                .filter(token -> token.getUserId().equals(user.getUserId()))
                .collect(Collectors.toList());

        for (TokenEntity token : userTokens) {
            token.markAsRevoked();
            // Remove from database
            TOKENS_DB.remove(token.getKey());
        }

        // Find and revoke one-time tokens for this user
        List<TokenEntity> oneTimeTokens = ONE_TIME_TOKENS.values()
                .stream()
                .filter(token -> token.getUserId().equals(user.getUserId()))
                .collect(Collectors.toList());

        for (TokenEntity token : oneTimeTokens) {
            token.markAsConsumed(); // Already marked as consumed
            ONE_TIME_TOKENS.remove(token.getKey());
        }

        // Return success response
        return ResponseEntity.ok(Map.of("message", "Logged out successfully"));
    }

    /**
     * POST /api/auth/validate-token
     * Accepts one-time token as JSON parameter
     * Validates and consumes one-time token
