        }

        // Token is valid - consume it atomically
        tokenEntity.markAsConsumed();
        ONE_TIME_TOKENS.remove(tokenEntity.getKey());

        // Return success response
        return ResponseEntity.ok(Map.of("valid", true, "message", "Token validated successfully"));
