                .stream()
                .filter(token -> token.getUserId().equals(user.getUserId()))
                .collect(Collectors.toList());

        for (TokenEntity token : oneTimeTokens) {
            // One-time tokens must be consumed (already marked as consumed)
            token.markAsConsumed();
