    private static final long ONE_TIME_TOKEN_EXPIRE_SECONDS = 300; // 5 minutes

    // Token storage - Map from tokenValue (unique identifier) to TokenEntity
    // Primary key is tokenValue for uniqueness
    private static final Map<String, TokenEntity> TOKENS_DB = new ConcurrentHashMap<>();

    // User storage - Map from userId to UserEntity
    private static final Map<String, UserEntity> USERS_DB = new ConcurrentHashMap<>();

    // One-time token tracking - Map from tokenValue to TokenEntity
    private static final Map<String, TokenEntity> ONE_TIME_TOKENS = new ConcurrentHashMap<>();

    // Track concurrent renewal attempts using AtomicInteger for thread safety
    private static final AtomicInteger concurrentRenewAttempts = new AtomicInteger(0);

    // Scheduled cleanup task executor
    private static final java.util.concurrent.Executors.newScheduledThreadPool(1, new java.util.concurrent.ThreadFactory() {
        public Thread newThread(Runnable r) {
            Thread t = new Thread(r, "TokenCleanup");
            t.setDaemon(true);
            return t;
        }
    }).start();

    // Start cleanup scheduler every 10 seconds
    @Scheduled(cron = "0/* * * * *")
    public void cleanupExpiredTokens() {
        int deletedCount = cleanupExpiredTokensFromDB();
        System.out.println("[CLEANUP] Deleted " + deletedCount + " tokens");
    }

    // Cleanup expired tokens from database
    private int cleanupExpiredTokensFromDB() {
        int deletedCount = 0;

        // Iterate through all tokens in database
        for (Map.Entry<String, TokenEntity> entry : TOKENS_DB.entrySet()) {
            TokenEntity token = entry.getValue();

            // Check if token needs cleanup
            boolean shouldDelete = false;

            // Check if expired
            if (token.getExpiresAt().isBefore(Instant.now())) {
                shouldDelete = true;
            }

            // Check if revoked
            if (token.isRevoked()) {
                shouldDelete = true;
            }

            // Check if consumed (one-time tokens)
            if (token.isConsumed()) {
                shouldDelete = true;
            }

            // Clean up if needed
            if (shouldDelete) {
                // Delete from database
                TOKENS_DB.remove(entry.getKey());

                // Also remove from one-time tokens map if it's a one-time token
                if (token.getTokenType().equals("ONE_TIME")) {
                    ONE_TIME_TOKENS.remove(entry.getKey());
                }

                deletedCount++;
            }
        }

        // Also cleanup one-time tokens map
        for (Map.Entry<String, TokenEntity> entry : ONE_TIME_TOKENS.entrySet()) {
            TokenEntity token = entry.getValue();

            // Check if token needs cleanup
            boolean shouldDelete = false;

            // Check if expired
            if (token.getExpiresAt().isBefore(Instant.now())) {
                shouldDelete = true;
            }

            // Check if revoked
            if (token.isRevoked()) {
                shouldDelete = true;
            }

            // Check if consumed
            if (token.isConsumed()) {
                shouldDelete = true;
            }

            // Clean up if needed
            if (shouldDelete) {
                // Delete from database
                TOKENS_DB.remove(entry.getKey());

                // Also remove from one-time tokens map
                ONE_TIME_TOKENS.remove(entry.getKey());

                deletedCount++;
            }
        }

        return deletedCount;
    }

    // ============ API Endpoints ============

    /**
     * POST /api/auth/login
     * Accepts username and password, returns tokens and sets refresh token cookie
     */
    @PostMapping("/api/auth/login")
    public ResponseEntity<Map<String, String>> login(@RequestBody(required = false) LoginRequest loginRequest) 
            throws IOException {

        // Validate input - Check if username and password are provided
        if (loginRequest == null || loginRequest.getUsername() == null || 
            loginRequest.getUsername().isEmpty() || 
            loginRequest.getPassword() == null || loginRequest.getPassword().isEmpty()) {
            return ResponseEntity.badRequest().build();
        }

        // Find user by username in database
        UserEntity user = USERS_DB.get(loginRequest.getUsername());
        if (user == null) {
            // User not found - return error
            return ResponseEntity.status(404).build();
        }

        // Validate credentials (in real system, compare with hash)
        // For this task, assume any non-empty username/password is valid

        // Issue three tokens atomically:
        // 1. Access Token (10 min)
        // 2. Refresh Token (24 hours)
        // 3. One-Time Token (5 min)

        String accessToken = generateNewAccessToken(user.getUserId());
        String refreshToken = generateNewRefreshToken(user.getUserId());
        String oneTimeToken = generateNewOneTimeToken();

        // Create TokenEntities with proper metadata
        TokenEntity accessTokenEntity = new TokenEntity(
            accessToken,
            user.getUserId(),
            "ACCESS",
            Instant.now(),
            Instant.now().plus(ACCESS_TOKEN_EXPIRE_MINS, ChronoUnit.MINUTES),
            false,
            false
        );

        TokenEntity refreshTokenEntity = new TokenEntity(
            refreshToken,
            user.getUserId(),
            "REFRESH",
            Instant.now(),
            Instant.now().plus(REFRESH_TOKEN_EXPIRE_SECONDS, ChronoUnit.SECONDS),
            false,
            false
        );

        TokenEntity oneTimeTokenEntity = new TokenEntity(
            oneTimeToken,
            user.getUserId(),
            "ONE_TIME",
            Instant.now(),
            Instant.now().plus(ONE_TIME_TOKEN_EXPIRE_SECONDS, ChronoUnit.SECONDS),
            false,
            false
        );

        // Store tokens in database
        TOKENS_DB.put(accessToken, accessTokenEntity);
        TOKENS_DB.put(refreshToken, refreshTokenEntity);
        ONE_TIME_TOKENS.put(oneTimeToken, oneTimeTokenEntity);

        // Create response with tokens
        Map<String, String> response = new HashMap<>();
        response.put("accessToken", accessToken);
        response.put("oneTimeToken", oneTimeToken);

        // Set Refresh Token as HTTP-only cookie with proper attributes
        HttpServletResponse response = (HttpServletResponse) getResponse();
        Cookie refreshTokenCookie = new Cookie("refreshToken", refreshToken);
        refreshTokenCookie.setHttpOnly(true);
        refreshTokenCookie.setMaxAge(86400); // 24 hours
        response.addCookie(refreshTokenCookie);

        // Return JSON response
        return ResponseEntity.ok(response);
    }

    /**
     * POST /api/auth/renew
     * Accepts Refresh Token from Cookie (name: refreshToken) OR Header (key: refreshToken)
     * If both present, Cookie takes precedence
     * Returns renewed tokens
     */
    @PostMapping("/api/auth/renew")
    public ResponseEntity<Map<String, Object>> renew(
            @RequestParam(name = "refreshToken", required = false) String refreshTokenFromHeader,
            @CookieValue(value = "refreshToken", required = false, name = "refreshToken") String refreshTokenFromCookie) 
            throws IOException {

        // Determine which source has the token
        // Cookie takes precedence over Header
        String effectiveRefreshToken = refreshTokenFromCookie != null && !refreshTokenFromCookie.isEmpty() 
                ? refreshTokenFromCookie 
                : (refreshTokenFromHeader != null && !refreshTokenFromHeader.isEmpty() ? refreshTokenFromHeader : "");

        // If no valid refresh token, return 401
        if (effectiveRefreshToken == null || effectiveRefreshToken.isEmpty()) {
            return ResponseEntity.status(401).body(Map.of("accessToken", "", "message", "Refresh token missing or invalid"));
        }

        // Find current token entity in database
        // Look for token with value matching the refresh token
        TokenEntity currentToken = TOKENS_DB.get(effectiveRefreshToken);
        if (currentToken == null) {
            return ResponseEntity.status(401).body(Map.of("accessToken", "", "message", "Invalid refresh token"));
        }

        // Check if token is revoked
        if (currentToken.isRevoked()) {
            return ResponseEntity.status(401).body(Map.of("accessToken", "", "message", "Refresh token has been revoked"));
        }

        // Check if token is expired
        if (currentToken.getExpiresAt().isBefore(Instant.now())) {
            return ResponseEntity.status(401).body(Map.of("accessToken", "", "message", "Refresh token has expired"));
        }

        // Handle concurrent renewal attempts - use atomic counter
        // Only allow one renewal to succeed for the same refresh token
        // Increment counter, if > 1, reject (409 Conflict)
        int currentAttempt = concurrentRenewAttempts.getAndIncrement();
        if (currentAttempt > 1) {
            // Concurrent access detected - reject with 409 Conflict
            return ResponseEntity.status(409).body(Map.of("accessToken", "", "message", "Concurrent renewal attempt detected"));
        }

        // Rotate tokens atomically:
        // 1. Revoke current Refresh Token
        currentToken.markAsRevoked();

        // 2. Issue new Refresh Token (24 hours)
        String newRefreshToken = generateNewRefreshToken(currentToken.getUserId());

        // 3. Issue new Access Token (10 minutes)
        String newAccessToken = generateNewAccessToken(currentToken.getUserId());

        // 4. Issue new One-Time Token (5 minutes)
        String newOneTimeToken = generateNewOneTimeToken();

        // Update database with new tokens
        // New Refresh Token
        TokenEntity newRefreshTokenEntity = new TokenEntity(
            newRefreshToken,
            currentToken.getUserId(),
            "REFRESH",
            Instant.now(),
            Instant.now().plus(REFRESH_TOKEN_EXPIRE_SECONDS, ChronoUnit.SECONDS),
            false,
            false
        );
        TOKENS_DB.put(newRefreshTokenEntity.getKey(), newRefreshTokenEntity);

        // New Access Token
        TokenEntity newAccessTokenEntity = new TokenEntity(
            newAccessToken,
            currentToken.getUserId(),
            "ACCESS",
            Instant.now(),
            Instant.now().plus(ACCESS_TOKEN_EXPIRE_MINS, ChronoUnit.MINUTES),
            false,
            false
        );
        TOKENS_DB.put(newAccessTokenEntity.getKey(), newAccessTokenEntity);

        // New One-Time Token
        TokenEntity newOneTimeTokenEntity = new TokenEntity(
            newOneTimeToken,
            currentToken.getUserId(),
            "ONE_TIME",
            Instant.now(),
            Instant.now().plus(ONE_TIME_TOKEN_EXPIRE_SECONDS, ChronoUnit.SECONDS),
            false,
            false
        );
        TOKENS_DB.put(newOneTimeTokenEntity.getKey(), newOneTimeTokenEntity);

        // Set new tokens in response
        Map<String, Object> response = new HashMap<>();
        response.put("accessToken", newAccessToken);

        // Return new refresh token as HTTP-only cookie
        HttpServletResponse response = (HttpServletResponse) getResponse();
        Cookie refreshTokenCookie = new Cookie("refreshToken", newRefreshToken);
        refreshTokenCookie.setHttpOnly(true);
        refreshTokenCookie.setMaxAge(86400);
        response.addCookie(refreshTokenCookie);

        return ResponseEntity.ok(response);
    }

    /**
     * POST /api/auth/logout
     * Accepts Access Token in Authorization header (Bearer <token>)
     * Returns 401 if Access Token is missing or invalid
     * Invalidates ALL tokens for the authenticated user
     */
    @PostMapping("/api/auth/logout")
    public ResponseEntity<Map<String, Object>> logout(
            @RequestHeader("Authorization") String authorizationHeader) {

        // Extract access token from Bearer token
        if (!authorizationHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(401).body(Map.of("message", "Invalid authorization header"));
        }

        String accessToken = authorizationHeader.substring(7);

        // Find access token entity
        TokenEntity accessTokenEntity = TOKENS_DB.get(accessToken);
        if (accessTokenEntity == null) {
            return ResponseEntity.status(401).body(Map.of("message", "Invalid access token"));
        }

        // Find user entity by user_id
        UserEntity user = USERS_DB.getIfPresent(accessTokenEntity.getUserId());
        if (user == null) {
            return ResponseEntity.status(404).body(Map.of("message", "User not found"));
        }

        // Invalidate ALL tokens for this user:
        // 1. Revoke Access Token
        accessTokenEntity.markAsRevoked();
        // Remove from database (since it's revoked)
        TOKENS_DB.remove(accessTokenEntity.getKey());

        // 2. Revoke Refresh Token (if exists for this user)
        // Find refresh token by user_id and revoke
        // Note: Refresh token value is unique, but we need to find by userId
        // Since we store tokens by tokenValue, we need to search again
        // Actually, we should find all tokens where userId matches
        // But our current implementation stores tokens by tokenValue
        // So we need to iterate TOKENS_DB values again and filter by userId
        List<TokenEntity> userTokens = TOKENS_DB.values()
                .stream()
                .filter(token -> token.getUserId().equals(user.getUserId()))
                .collect(Collectors.toList());

        for (TokenEntity token : userTokens) {
            // Revoke the token
            token.markAsRevoked();
            // Remove from database
            TOKENS_DB.remove(token.getKey());
        }

        // 3. Revoke One-Time Tokens (if exists for this user)
        List<TokenEntity> oneTimeTokens = ONE_TIME_TOKENS.values()
                .stream()
                .filter(token -> token.getUserId().equals(user.getUserId()))
                .collect(Collectors.toList());

        for (TokenEntity token : oneTimeTokens) {
            // One-time tokens must be consumed (already marked as consumed)
            token.markAsConsumed();
            // Remove from database
            ONE_TIME_TOKENS.remove(token.getKey());
        }

        // Return success response
        return ResponseEntity.ok(Map.of("message", "Logged out successfully"));
    }

    /**
     * POST /api/auth/validate-token
     * Accepts one-time token as JSON parameter
     * Validates and consumes one-time token
     */
    @PostMapping("/api/auth/validate-token")
    public ResponseEntity<Map<String, Object>> validateToken(
            @RequestBody(required = false) ValidateTokenRequest validateRequest) {

        if (validateRequest == null || validateRequest.getToken() == null || validateRequest.getToken().isEmpty()) {
            return ResponseEntity.status(400).body(Map.of("valid", false, "message", "Token parameter missing"));
        }

        String tokenToValidate = validateRequest.getToken();

        // Find token entity in ONE_TIME_TOKENS map
        TokenEntity tokenEntity = ONE_TIME_TOKENS.get(tokenToValidate);
        if (tokenEntity == null) {
            // Token not found in database
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", "Token not found"));
        }

        // Check if token is revoked
        if (tokenEntity.isRevoked()) {
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", "Token has been revoked"));
        }

        // Check if token is expired
        if (tokenEntity.getExpiresAt().isBefore(Instant.now())) {
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", "Token has expired"));
        }

        // Token is valid - consume it atomically
        // Mark as consumed and remove from database
        tokenEntity.markAsConsumed();
        ONE_TIME_TOKENS.remove(tokenEntity.getKey());

        // Return success response
        return ResponseEntity.ok(Map.of("valid", true, "message", "Token validated successfully"));
    }

    // ============ Helper Methods ============

    /**
     * Generate unique access token (includes user ID for uniqueness)
     */
    private String generateNewAccessToken(String userId) {
        return "access_token_" + userId + "_" + System.currentTimeMillis() + "_" + 
               UUID.randomUUID().toString().replace("-", "");
    }

    /**
     * Generate unique refresh token
     */
    private String generateNewRefreshToken(String userId) {
        return "refresh_token_" + userId + "_" + System.currentTimeMillis() + "_" + 
               UUID.randomUUID().toString().replace("-", "");
    }

    /**
     * Generate unique one-time token
     */
    private String generateNewOneTimeToken() {
        return "one_time_token_" + System.currentTimeMillis() + "_" + 
               UUID.randomUUID().toString().replace("-", "");
    }

    /**
     * Login Request DTO
     */
    private static class LoginRequest {
        private String username;
        private String password;

        public String getUsername() {
            return username;
        }

        public void setUsername(String username) {
            this.username = username;
        }

        public String getPassword() {
            return password;
        }

        public void setPassword(String password) {
            this.password = password;
        }
    }

    /**
     * Validate Token Request DTO
     */
    private static class ValidateTokenRequest {
        private String token;

        public String getToken() {
            return token;
        }

        public void setToken(String token) {
            this.token = token;
        }
    }
}
