            return ResponseEntity.status(400).body(Map.of("valid", false, "message", "Token parameter missing"));
        }

        String tokenToValidate = validateRequest.getToken();

        // Find token entity in ONE_TIME_TOKENS map
        TokenEntity tokenEntity = ONE_TIME_TOKENS.get(tokenToValidate);
        if (tokenEntity == null) {
            // Token not found in database
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", "Token not found"));
        }

        // Check if token is revoked
        if (tokenEntity.isRevoked()) {
            return ResponseEntity.status(401).body(Map.of("valid", false, "message", "Token has been revoked"));
